#include "goal1_native_scri_leading.hpp"
#include <iostream>
#include <iomanip>
#include <string>
#include <cstdlib>
#include <vector>
namespace cs=cubed_sphere;namespace h=z4c::hyperboloidal;
double Read(){std::string s;if(!(std::cin>>s))throw std::runtime_error("missing leading fixture");char*end;double x=std::strtod(s.c_str(),&end);if(*end||!std::isfinite(x))throw std::runtime_error("invalid leading fixture");return x;}
std::array<double,22> last_rows;
double MaxPole(const h::Z4cJet<Real>&u,const h::LayerPoint<Real>&p,const Real x[3]){auto ref=cs::native_endpoint::OuterReference(p,x);ref.omega.f=0;auto f=cs::native_endpoint::NativeParts(cs::native_endpoint::Spatial(u),ref,cs::native_endpoint::OuterConnection(x));if(!f.valid)throw std::runtime_error("invalid actual native leading parts");double m=0;for(int n=0;n<22;++n){last_rows[n]=f.pole[n].f;m=std::max(m,std::abs(f.pole[n].f));}return m;}
int main(int argc,char**argv){Kokkos::initialize(argc,argv);std::cout<<std::setprecision(17);int status=0;try{while(std::cin>>std::ws,std::cin.peek()!=EOF){int id=Read();Real x[3];for(auto&v:x)v=Read();h::Z4cJet<Real>empty{};auto input=cs::typed_support::Map<Real>(empty,[](int,Real){return Read();});auto answer=cs::native_scri_leading::Solve(input,x);if(!answer.valid)throw std::runtime_error("singular leading chart");double error=0;std::vector<double>target;cs::typed_support::Map<Real>(input,[&](int,Real q){target.push_back(q);return q;});cs::typed_support::Map<Real>(answer.u,[&](int i,Real q){error=std::max(error,std::abs(q-target[i])/std::max({1.,std::abs(q),std::abs(target[i])}));return q;});h::LayerReference<Real>descriptor(1.,.5,{true,.05,.95});auto p=descriptor.At(x[0],x[1],x[2]);double pole=MaxPole(answer.u,p,x);auto rows=last_rows;auto completion=cs::native_endpoint::Evaluate(answer.u,p,x);auto gt=h::Geometry(answer.u.metric);double trace=0;for(int i=0;i<3;++i)for(int j=0;j<3;++j)trace+=gt.inverse[i][j]*answer.u.a.k[i][j];auto bad=answer.u;for(int i=0;i<3;++i)for(int j=0;j<3;++j)bad.a.k[i][j]=0;double noA=MaxPole(bad,p,x);bad=answer.u;bad.alpha.value=2;bad.trace.value=-6;for(int i=0;i<3;++i)bad.beta.value[i]=-2*x[i];double reflead=MaxPole(bad,p,x);bad=answer.u;for(int i=0;i<3;++i)bad.lambda.value[i]=gt.contracted[i];double noZ=MaxPole(bad,p,x);std::cout<<"{\"completion_valid\":"<<(completion.valid?"true":"false")<<",\"completion_pole_tangent\":"<<completion.tangent<<",\"completion_pole_second\":"<<completion.second<<",\"pole_rows\":[";for(int n=0;n<22;++n){if(n)std::cout<<",";std::cout<<rows[n];}std::cout<<"],\"id\":"<<id<<",\"value_error\":"<<error<<",\"actual_native22_pole\":"<<pole<<",\"A_trace\":"<<std::abs(trace)<<",\"tangential_divisor\":"<<answer.tangential<<",\"normal_divisor\":"<<answer.normal<<",\"scalar_gap\":"<<answer.scalar_gap<<",\"negative_no_A\":"<<noA<<",\"negative_reference_leading\":"<<reflead<<",\"negative_no_Z_feedback\":"<<noZ<<"}\n";}}catch(const std::exception&e){std::cerr<<e.what()<<'\n';status=1;}Kokkos::finalize();return status;}
